package personalize

import (
	"fmt"
	"sort"
	"sync"

	"github.com/braedonsaunders/ether/internal/core"
	"github.com/braedonsaunders/ether/internal/extend"
)

// RowSourceKind is one Home Designer row source: a family of rows the
// owner can place, schedule or hide with layout policies. Built-in row
// families are generated by the engine's existing builders (kinds.go);
// the kind registry is how they are described and served. A runtime kind
// (a plugin list source offered as a row, WS9) registers a kind whose
// rows arrive through a collection with a Home row target, and sets
// CollectionSource in its descriptor meta to the gathering kind.
//
// To add a built-in row family: add its kindInfo in kinds.go (title,
// description, group, surfaces) and its builder; it appears here
// automatically. To add a runtime kind: implement RowSourceKind and call
// Engine.RegisterRowSourceKind, then serve RowKindRegistry.Descriptors
// (extend form) through the extend registry.
type RowSourceKind interface {
	Kind() string
	Descriptor() core.RowDescriptor
}

// builtinRowKind adapts a static kindInfo.
type builtinRowKind struct{ info kindInfo }

func (b builtinRowKind) Kind() string { return b.info.kind }
func (b builtinRowKind) Descriptor() core.RowDescriptor {
	k := b.info
	return core.RowDescriptor{HubID: k.kind, Title: k.title, Kind: k.kind, Description: k.description,
		Sections: append([]string(nil), kindFits(k)...), Group: k.group}
}

// RowKindRegistry holds the row source kinds. Safe for concurrent use.
type RowKindRegistry struct {
	mu    sync.RWMutex
	kinds map[string]RowSourceKind
	order []string
}

func NewRowKindRegistry() *RowKindRegistry {
	r := &RowKindRegistry{kinds: map[string]RowSourceKind{}}
	for _, k := range kinds {
		if err := r.Register(builtinRowKind{info: k}); err != nil {
			panic("personalize: " + err.Error())
		}
	}
	return r
}

func (r *RowKindRegistry) Register(k RowSourceKind) error {
	if k == nil || k.Kind() == "" {
		return fmt.Errorf("row source kind needs a kind")
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, ok := r.kinds[k.Kind()]; ok {
		return fmt.Errorf("row source kind %q already registered", k.Kind())
	}
	r.kinds[k.Kind()] = k
	r.order = append(r.order, k.Kind())
	return nil
}

// Unregister removes a runtime row source kind by kind id.
func (r *RowKindRegistry) Unregister(kind string) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, ok := r.kinds[kind]; !ok {
		return
	}
	delete(r.kinds, kind)
	out := r.order[:0]
	for _, cur := range r.order {
		if cur != kind {
			out = append(out, cur)
		}
	}
	r.order = out
}

func (r *RowKindRegistry) Lookup(kind string) (RowSourceKind, bool) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	k, ok := r.kinds[kind]
	return k, ok
}

func (r *RowKindRegistry) Kinds() []RowSourceKind {
	r.mu.RLock()
	defer r.mu.RUnlock()
	out := make([]RowSourceKind, 0, len(r.order))
	for _, id := range r.order {
		out = append(out, r.kinds[id])
	}
	return out
}

// RowDescriptors returns the Home Designer catalogue: registered kinds in
// registration order, then dynamic rows (owner collections, extra hubs)
// sorted by title. This is exactly what AvailableRows serves.
func (r *RowKindRegistry) RowDescriptors(extra []core.RowDescriptor) []core.RowDescriptor {
	kinds := r.Kinds()
	out := make([]core.RowDescriptor, 0, len(kinds)+len(extra))
	for _, k := range kinds {
		out = append(out, k.Descriptor())
	}
	sort.SliceStable(extra, func(i, j int) bool { return extra[i].Title < extra[j].Title })
	return append(out, extra...)
}

// Descriptors returns the extend rowSource descriptors for every kind.
// Titles and descriptions are the English strings the layout API already
// serves for these rows.
func (r *RowKindRegistry) Descriptors() []extend.Descriptor {
	kinds := r.Kinds()
	out := make([]extend.Descriptor, 0, len(kinds))
	for i, k := range kinds {
		d := k.Descriptor()
		out = append(out, extend.Descriptor{
			Kind: extend.KindRowSource, ID: d.Kind, Owner: extend.Builtin,
			Label: extend.Text{Source: d.Title}, Hint: extend.Text{Source: d.Description},
			Group: d.Group, Order: (i + 1) * 10,
		}.WithMeta(extend.RowSourceMeta{
			HubID: d.HubID, RowKind: d.Kind, Sections: d.Sections,
			Source: infoFor(d.Kind).source,
		}))
	}
	return out
}

var defaultRowKinds = NewRowKindRegistry()

// BuiltinRowDescriptors returns extend descriptors for the built-in row
// kinds, without an Engine (app startup registers these).
func BuiltinRowDescriptors() []extend.Descriptor { return defaultRowKinds.Descriptors() }

func (e *Engine) rowKindRegistry() *RowKindRegistry {
	if e.rowKinds != nil {
		return e.rowKinds
	}
	return defaultRowKinds
}

// RegisterRowSourceKind adds a row source kind to this engine.
func (e *Engine) RegisterRowSourceKind(k RowSourceKind) error { return e.rowKindRegistry().Register(k) }

// UnregisterRowSourceKind removes a runtime row source kind from this engine.
func (e *Engine) UnregisterRowSourceKind(kind string) { e.rowKindRegistry().Unregister(kind) }

// RowKindRegistry exposes this engine's row-kind registry.
func (e *Engine) RowKindRegistry() *RowKindRegistry { return e.rowKindRegistry() }
